function fileSeverity(record, reason) {
  if (record.kind === 'ERROR') return 'critical';
  if (record.kind === 'IOC_FILE') return 'critical';
  if (record.kind === 'UPLOAD_EXEC') return 'critical';
  if (record.kind === 'MU_FILE' && !ALLOWED_MU_FILES.has(record.path)) return 'critical';
  if (record.kind === 'PLUGIN_DIR' && reason === 'new_record') return 'critical';
  if (record.kind === 'CRITICAL_FILE' && reason === 'changed') return 'critical';
  return 'warning';
