function analyzeDb(section) {
  const findings = [];
  const baseline = { initialized: false, updated: false };
  if (!section || section.status !== 'ok') {
    findings.push({ severity: 'critical', source: 'db-watchdog', reason: 'agent_error', message: section && section.error_output ? section.error_output : 'DB watchdog did not return a valid payload.' });
    return { findings, baseline };
  }

  const rows = section.payload && Array.isArray(section.payload.records) ? section.payload.records : [];
  const current = {};
  for (const row of rows) current[stableDbKey(row)] = dbSummary(row);

  const firstRunFindings = [];
  for (const row of rows) {
    if (row.record_type === 'admin_user' && !KNOWN_ADMIN_IDS.has(String(row.key_name))) {
      firstRunFindings.push({ severity: 'critical', source: 'db-watchdog', reason: 'admin_not_in_allowlist', record: dbSummary(row) });
    }
    if (row.record_type === 'suspicious_option') {
      firstRunFindings.push({ severity: 'critical', source: 'db-watchdog', reason: 'suspicious_option_payload', record: dbSummary(row) });
    }
  }

  if (RESET_BASELINES || !state.dailyDbBaseline) {
    state.dailyDbBaseline = { initialized_at: new Date().toISOString(), records: current };
    baseline.initialized = true;
    if (ALERT_ON_FIRST_RUN_FINDINGS) findings.push(...firstRunFindings);
    return { findings, baseline };
  }

  const previous = state.dailyDbBaseline.records || {};
  for (const key of Object.keys(current)) {
    const row = current[key];
    const old = previous[key];
