  state.dailyDbBaseline = { initialized_at: state.dailyDbBaseline.initialized_at, updated_at: new Date().toISOString(), records: current };
  baseline.updated = true;
  return { findings, baseline };
}

function analyzeFile(section) {
  const findings = [];
  const baseline = { initialized: false, updated: false };
  if (!section || section.status !== 'ok') {
    findings.push({ severity: 'critical', source: 'file-watchdog', reason: 'agent_error', message: section && section.error_output ? section.error_output : 'File watchdog did not return a valid payload.' });
    return { findings, baseline };
  }

  const records = section.payload && Array.isArray(section.payload.records) ? section.payload.records : [];
  const current = {};
  for (const record of records) current[fileKey(record)] = fileSummary(record);

  const firstRunFindings = [];
  for (const record of records) {
    if (record.kind === 'ERROR' || record.kind === 'IOC_FILE' || record.kind === 'UPLOAD_EXEC' || (record.kind === 'MU_FILE' && !ALLOWED_MU_FILES.has(record.path))) {
      firstRunFindings.push({ severity: fileSeverity(record, 'first_run'), source: 'file-watchdog', reason: 'first_run_sensitive_file', record: fileSummary(record) });
    }
  }

  if (RESET_BASELINES || !state.dailyFileBaseline) {
    state.dailyFileBaseline = { initialized_at: new Date().toISOString(), records: current };
    baseline.initialized = true;
    if (ALERT_ON_FIRST_RUN_FINDINGS) findings.push(...firstRunFindings);
    return { findings, baseline };
  }

  const previous = state.dailyFileBaseline.records || {};
  for (const key of Object.keys(current)) {
    const record = current[key];
    const old = previous[key];
    if (!old) {
      findings.push({ severity: fileSeverity(record, 'new_record'), source: 'file-watchdog', reason: 'new_record', record: record });
      continue;
    }
    if (record.kind === 'CRITICAL_FILE' && String(old.hash || '') !== String(record.hash || '')) {
      findings.push({ severity: fileSeverity(record, 'changed'), source: 'file-watchdog', reason: 'critical_file_hash_changed', old_record: old, record: record });
    }
  }

  for (const key of Object.keys(previous)) {
    if (!current[key]) {
      const old = previous[key];
      if (old.kind === 'CRITICAL_FILE' || old.kind === 'MU_FILE') {
        findings.push({ severity: 'warning', source: 'file-watchdog', reason: 'sensitive_record_removed', old_record: old });
      }
    }
  }

  state.dailyFileBaseline = { initialized_at: state.dailyFileBaseline.initialized_at, updated_at: new Date().toISOString(), records: current };
  baseline.updated = true;
  return { findings, baseline };
}

function analyzeLocal(local) {
  const findings = [];
  if (!local || local.status !== 'ok') {
    findings.push({ severity: 'warning', source: 'local-watchdog', reason: 'local_log_warning', message: local && local.message ? local.message : 'Local Watchdog summary is not ok.' });
  }
  const samples = local && Array.isArray(local.samples) ? local.samples : [];
  for (const sample of samples) {
    const severity = String(sample.severity || 'info').toLowerCase();
    if (severity === 'critical' || severity === 'warning') {
      findings.push({ severity, source: 'local-watchdog', reason: 'local_event_sample', event: sample });
    }
  }
  return findings;
}

const db = analyzeDb(payload.db_watchdog || {});
const file = analyzeFile(payload.file_watchdog || {});
const localFindings = analyzeLocal(payload.local_watchdog || {});
const findings = [...localFindings, ...db.findings, ...file.findings];
const hasCritical = findings.some(function(f) { return f.severity === 'critical'; });
const hasWarning = findings.some(function(f) { return f.severity === 'warning'; });
const severity = hasCritical ? 'critical' : (hasWarning ? 'warning' : 'info');

return [{
  json: Object.assign({}, payload, {
    severity,
    findings,
    local_findings: localFindings,
    db_findings: db.findings,
    file_findings: file.findings,
    baseline: {
      db: db.baseline,
      file: file.baseline
    },
    analyzed_at: new Date().toISOString()
  })
}];

const input = items[0] && items[0].json ? items[0].json : {};

function escapeHtml(value) {
  return String(value === undefined || value === null ? '' : value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function asJson(value) {
  return escapeHtml(JSON.stringify(value || {}, null, 2));
}

function severityColor(severity) {
  if (severity === 'critical') return '#b42318';
  if (severity === 'warning') return '#b54708';
  return '#027a48';
}

function rowsFromObject(obj) {
  const entries = Object.entries(obj || {}).sort(function(a, b) { return Number(b[1]) - Number(a[1]); });
  if (!entries.length) return '<tr><td colspan="2"><em>None</em></td></tr>';
  return entries.map(function(entry) {
    return '<tr><td style="padding:4px 8px;border-bottom:1px solid #ddd;"><code>' + escapeHtml(entry[0]) + '</code></td><td style="padding:4px 8px;border-bottom:1px solid #ddd;text-align:right;">' + escapeHtml(entry[1]) + '</td></tr>';
  }).join('');
}

function findingList(findings) {
  if (!findings.length) return '<p><em>No critical or warning findings.</em></p>';
  return '<ul>' + findings.map(function(finding) {
    const record = finding.record || finding.old_record || finding.event || {};
    const label = record.path || record.key_name || record.event_type || finding.message || '';
    return '<li><strong>' + escapeHtml(finding.severity || '') + '</strong> '
      + escapeHtml(finding.source || '') + ' / ' + escapeHtml(finding.reason || '')
      + (label ? ' - <code>' + escapeHtml(label) + '</code>' : '')
      + '</li>';
  }).join('') + '</ul>';
}

